using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking Change #3: EF Core 9 throws if you call Migrate() inside a
    // user-opened transaction. Migrate manages its own transactions internally.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }

    // Breaking Change #1 (Cosmos sync I/O): Use async queries for Cosmos.
    // EF Core 9 Cosmos provider removed synchronous query support.
    async Task QueryProductsAsync(CosmosDbContext cosmosDb)
    {
        // Before (broken in EF9): cosmosDb.Products.ToList();
        var products = await cosmosDb.Products.ToListAsync();
    }
}

